-- Official CDC/NCHS FY2027 code descriptions; organizing families are application metadata.
create table public.emr_diagnosis_catalog (
 code text primary key, label text not null, category text not null,
 group_code text not null, group_label text not null,
 version text not null default 'ICD-10-CM FY2027'
);
alter table public.emr_diagnosis_catalog enable row level security;
revoke all on public.emr_diagnosis_catalog from public,anon,authenticated;
grant select on public.emr_diagnosis_catalog to authenticated;
create policy diagnosis_catalog_read on public.emr_diagnosis_catalog for select to authenticated
 using ((select private.modality_role()) in ('admin','staff'));

alter table public.emr_treatment_modalities add column diagnoses jsonb not null default '[]';
grant update(diagnoses) on public.emr_treatment_modalities to authenticated;
create table public.emr_diagnosis_versions (
 patient_id uuid not null references public.clinical_patients(id),
 revision integer not null,
 diagnoses jsonb not null,
 recorded_by uuid not null references auth.users(id),
 recorded_at timestamptz not null default now(),
 primary key(patient_id,revision)
);
alter table public.emr_diagnosis_versions enable row level security;
revoke all on public.emr_diagnosis_versions from public,anon,authenticated;
grant select on public.emr_diagnosis_versions to authenticated;
create policy diagnosis_history_read on public.emr_diagnosis_versions for select to authenticated
 using (exists (select 1 from public.emr_treatment_modalities m where m.patient_id=emr_diagnosis_versions.patient_id));

create function private.guard_emr_diagnoses() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 if jsonb_typeof(new.diagnoses) is distinct from 'array' then raise exception 'Invalid diagnosis table'; end if;
 if jsonb_array_length(new.diagnoses)>30 or octet_length(new.diagnoses::text)>60000 then raise exception 'Use up to 30 diagnoses'; end if;
 if exists (
  select 1 from jsonb_array_elements(new.diagnoses) d
  where jsonb_typeof(d) is distinct from 'object'
   or coalesce(d->>'priority','') not in ('primary','secondary')
   or coalesce(d->>'status','') not in ('confirmed','provisional','rule_out')
   or jsonb_typeof(d->'notes') is distinct from 'string' or char_length(d->>'notes')>1000
   or (select count(*) from jsonb_object_keys(case when jsonb_typeof(d)='object' then d else '{}'::jsonb end))<>6
   or not exists (select 1 from public.emr_diagnosis_catalog c where c.code=d->>'code' and c.label=d->>'label' and c.version=d->>'version')
 ) then raise exception 'Choose a valid diagnosis and ICD-10-CM code'; end if;
 if (select count(*) from jsonb_array_elements(new.diagnoses) d where d->>'priority'='primary')>1 then raise exception 'Choose only one primary diagnosis'; end if;
 if (select count(distinct d->>'code') from jsonb_array_elements(new.diagnoses) d)<>jsonb_array_length(new.diagnoses) then raise exception 'Do not duplicate diagnosis codes'; end if;
 return new;
end;
$$;
create trigger emr_diagnosis_guard before insert or update of diagnoses on public.emr_treatment_modalities
 for each row execute function private.guard_emr_diagnoses();

-- Trigger-only append: clients cannot insert, overwrite, or delete saved versions.
create function private.record_emr_diagnosis_version() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or private.modality_role() not in ('admin','staff') then raise exception 'Clinic sign-in and MFA required'; end if;
 if (tg_op='INSERT' and new.diagnoses<>'[]'::jsonb) or (tg_op='UPDATE' and new.diagnoses is distinct from old.diagnoses) then
  values(new.patient_id,new.revision,new.diagnoses,auth.uid());
 end if;
 return new;
end;
$$;
create trigger emr_diagnosis_history after insert or update of diagnoses on public.emr_treatment_modalities
 for each row execute function private.record_emr_diagnosis_version();
revoke all on function private.guard_emr_diagnoses(),private.record_emr_diagnosis_version() from public,anon,authenticated;
